-- 020: intercooler upgrade guide, diverter valve options, headlights to Exterior, turbo kit links and videos
-- Run in the Supabase SQL editor after 019. Safe to re-run.

-- 1. Intercooler upgrade (shared FSI/TSI)
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('intercooler','bpy','intercooler','Intercooler upgrade','Engine',null,array['intercooler','fmic','front mount','charge pipe','throttle body pipe','heat soak','ic']::text[],true,'3–5 hr',3) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('intercooler-tsi','ccta','intercooler','Intercooler upgrade','Engine',null,array['intercooler','fmic','front mount','charge pipe','throttle body pipe','heat soak','ic']::text[],true,'3–5 hr',3) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('intercooler',$j${"id": "intercooler", "title": "Intercooler upgrade", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "intercooler-temps", "alsoFits": "Mk5 Jetta GLI, Mk6 GTI, Eos, A3 8P 2.0T share the sandwich intercooler and most kits; charge pipes differ FSI vs TSI", "category": "Engine", "kind": "upgrade", "variants": {"questions": [{"question": "Which style of intercooler?", "hint": "The factory core is sandwiched between the A/C condenser and the radiator, low behind the bumper. You can replace it with a bigger core in that same spot (APR, IE, CTS, Neuspeed: direct fit, bumper and radiator support come off), or hang a large front-mount core off the crash beam behind the bumper cover (ECS, Eurojet, Godspeed) fed by new hoses, leaving the factory core in place or removed.", "options": [{"id": "stock", "label": "OE-location upgrade (bigger core, same spot)", "when": "Cleanest look, keeps factory airflow to the radiator, uses the factory hose routing. More disassembly on the day."}, {"id": "fmic", "label": "Front-mount kit (core behind the bumper)", "when": "Coolest outlet temps, easiest access later, visible through the grille. New hose runs; some kits drop core volume behind the radiator."}]}, {"question": "Replacing the charge pipes too?", "hint": "Between the turbo and the throttle body there are three pieces you can swap while the front is apart: the turbo outlet pipe (the plastic 'pancake' on the FSI), the intercooler hoses, and the throttle body pipe with the MAP sensor on it. Kits come both ways: 'for OEM charge pipes' or 'with charge pipes'.", "options": [{"id": "nopipes", "label": "Intercooler only", "when": "Keep the factory turbo outlet, hoses (where the kit reuses them) and throttle body pipe."}, {"id": "pipes", "label": "Intercooler plus charge pipes", "when": "Metal turbo outlet pipe, silicone hoses, aluminium throttle body pipe. Adds an hour and the noise-pipe plug."}]}]}, "chapters": [{"id": "plan", "title": "1 · Plan", "blurb": "Which core, which kit, and what it's worth on your car."}, {"id": "access", "title": "2 · Access", "blurb": "Bumper off. The OE-location route also puts the radiator support in service position."}, {"id": "cooler", "title": "3 · Cooler", "blurb": "Old core out and new one in, or the front-mount hung on the crash beam."}, {"id": "pipes", "title": "4 · Charge pipes", "blurb": "Turbo outlet, hoses, throttle body pipe and the MAP sensor."}, {"id": "finish", "title": "5 · Finish", "blurb": "Bumper back, coolant (OE route), leak check, and a heat-soak test you can actually feel."}], "glance": {"timeFirst": "3–5 hr (OE-location) · 2–3 hr (front-mount)", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$450–1,100 core · +$250–450 charge pipes", "risk": "Coolant everywhere on the OE route · a boost leak at a coupler you can't see · condenser lines bent while tilting it", "why": "The factory intercooler is a thin core wedged between two heat exchangers. On a tuned car it soaks after two hard pulls and the ECU starts pulling timing to protect the engine; APR measured the stock car doing exactly that on the third dyno run. A bigger core, or a core out in fresh air, keeps intake temps flat pull after pull. It doesn't add peak power so much as stop the car losing it.", "note": "Procedure from an OE-location kit's install sheet (IE) and front-mount kit documentation (ECS); temperature and power figures are vendor dyno claims, plotted as shapes."}, "heroCap": "Outlet air temperature across five back-to-back pulls. The stock core climbs until the tune protects itself; upgraded cores stay flat. Shapes anchored to APR and ECS test claims.", "lifespan": {"title": "What to expect", "headline": ["Flat intake temps pull after pull; 5–15 whp back on a tuned car that was heat-soaking, more on a K04"], "earliest": "The first hot day after a tune is when owners notice the stock core", "detail": "On a stock car the gain is small and the point is headroom. On a Stage 2 or K04 car the gain is whatever the tune was pulling in timing on hot days, which owners describe as the car 'not falling on its face' on the third pull. ECS measured +9 whp and +10 wtq with a 66 °F lower outlet on a K04 Mk6; APR measured the stock core letting temps run about 40 °F higher by the fifth pull.", "factors": ["Ambient temperature and how you drive it (heat soak is a repeated-pull problem)", "Boost level: K04 cars need this, Stage 1 cars want it", "Core volume vs pressure drop: a huge dense core costs boost response"], "inspect": ["Log intake air temperature (IAT) on repeated pulls before and after; the number on the third pull is the one that matters", "Look at every coupler after the first week: a slow boost leak shows as an oily ring at the clamp"], "confidence": {"level": "community", "n": 4, "note": "Vendor dyno claims from two suppliers plus owner reports; no independent comparison test across kits."}}, "should": {"yesIf": ["Tuned (Stage 1+) and the car feels weaker on the third hard pull than the first", "Planning a K04 or bigger; every vendor lists an intercooler as required", "Logging shows intake temps climbing 30 °F or more over back-to-back pulls", "Original intercooler with bent fins or a weeping end tank"], "codes": [], "notes": ["Both FSI and TSI Mk5 cars use the same sandwich intercooler and take the same cores; the charge pipes differ (the FSI's turbo outlet is the plastic 'pancake', the TSI's is a different pipe), so buy pipe kits by engine.", {"only": ["stock"], "text": "OE-location cores: APR (2.25 × 16.25 × 22 in, 40 % larger than stock, comes with hoses and a billet adapter), IE FDS (direct fit, install guide is public and is the one this procedure follows), CTS and Neuspeed direct-fit cores. All keep factory airflow through the radiator behind them."}, {"only": ["fmic"], "text": "Front-mount kits: ECS (23⅝ × 6½ × 3 in bar-and-plate, bolt-on brackets, sold 'for OEM charge pipes' or 'with ECS charge pipes'), Eurojet, Godspeed. Forge's Twintercooler is a hybrid: a second core in front of the crash bar plumbed in series with the factory core, keeping both."}, {"only": ["pipes"], "text": "Charge pipes: ECS, CTS and IE make FSI turbo outlet pipes and throttle body pipes; APR and IE sell hose sets. The throttle body pipe usually drops the factory noise pipe: buy the firewall plug (ECS ES#263635) with it."}, "Not legal for road use in California on a pollution-controlled vehicle; other states vary."], "confidence": {"level": "high", "n": 4, "note": "Kit contents, dimensions and fitment from vendor listings and install sheets agree."}}, "parts": [{"tier": "aftermarket", "name": "OE-location intercooler kit", "pn": "APR IC100016 · IE IETPCB1 · CTS CTS-IC-MK5 · Neuspeed", "note": "Core, silicone hoses, clamps, hardware; IE includes condenser spacers", "price": "$550–1,000", "links": [{"store": "IE (install guide)", "url": "https://cdn.performancebyie.com/guides/IETPCB1%20-%20MK5_MK6_IC_INSTALL_GUIDE.pdf"}, {"store": "APR product page", "url": "https://www.goapr.com/products/engine_hardware/charge_air_coolers/air_to_air_coolers/apr_intercooler_system_-_pq35_18t_and_20t/"}], "only": ["stock"]}, {"tier": "aftermarket", "name": "Front-mount intercooler kit", "pn": "ECS 007812LA01-01KT (for OEM pipes) · Eurojet · Godspeed", "note": "Core, cast end tanks, brackets, 4-ply couplers, T-bolt clamps", "price": "$450–900", "links": [{"store": "ECS Tuning", "url": "https://www.ecstuning.com/b-ecs-parts/mk5-gti-jetta-front-mount-intercooler-kit-for-oem-charge-pipes/007812la01-01kt/"}], "only": ["fmic+nopipes"]}, {"tier": "aftermarket", "name": "Front-mount intercooler kit with charge pipes", "pn": "ECS 007812LA01-02KT/-03KT · Eurojet with pipes", "note": "Adds turbo outlet pipe, throttle body pipe with MAP flange, all couplers", "price": "$750–1,100", "links": [{"store": "ECS Tuning (TSI kit page; FSI variant listed alongside)", "url": "https://www.ecstuning.com/b-ecs-parts/mk5-gti-jetta-tsi-front-mount-intercooler-kit-with-ecs-charge-pipes/007812la01-03kt/"}], "only": ["fmic+pipes"]}, {"tier": "aftermarket", "name": "Turbo outlet pipe (FSI 'pancake' replacement)", "pn": "CTS TOP · ECS · IE", "note": "Metal, with the DV port where your valve sits", "price": "$120–200", "links": [], "only": ["stock+pipes"]}, {"tier": "aftermarket", "name": "Throttle body pipe", "pn": "CTS · ECS · Neuspeed", "note": "Aluminium, MAP sensor flange, noise-pipe delete", "price": "$120–180", "links": [], "only": ["stock+pipes"]}, {"tier": "oe", "name": "Noise pipe firewall plug", "pn": "ES#263635 (ECS) or equivalent", "note": "Covers the hole the noise pipe leaves", "price": "$10", "links": [], "only": ["pipes"]}, {"tier": "oe", "name": "Intercooler hose o-ring (turbo outlet joint)", "pn": "reuse from the factory hose or buy new", "note": "IE's adapter takes the factory o-ring", "price": "$4", "links": [], "only": ["stock"]}, {"tier": "oe", "name": "Coolant, G12++/G13, one gallon premixed", "pn": "G 012 A8G / G 013 A8J", "note": "Radiator comes out on the OE route", "price": "$20", "links": [], "only": ["stock"]}, {"tier": "oe", "name": "Two long M10 bolts for service position", "pn": "M10 × 75 mm (IE includes them)", "note": "Holds the radiator support while it's slid forward", "price": "$4", "links": [], "only": ["stock"]}, {"tier": "oe", "name": "T-bolt clamps, spare", "pn": "60–80 mm ×2", "note": "Kits include them; one always gets dropped", "price": "$12", "links": []}], "aftermarket": [{"name": "APR Intercooler System (OE location)", "note": "Bar-and-plate, louvered fins, cast tanks, billet adapter. APR's own five-pull test: about 40 °F cooler than stock by run five, with the stock car pulling boost from run three.", "price": "$850–1,000", "signal": "Reference", "links": []}, {"name": "IE FDS intercooler (OE location)", "note": "Flow-distribution end tanks, public install guide, condenser spacers in the box. Best-documented install of the group.", "price": "$600–750", "signal": "Documented", "links": []}, {"name": "ECS front-mount kit", "note": "Bolt-on brackets, no drilling. ECS's dyno on a K04 Mk6: +9 whp, +10 wtq, 66 °F lower outlet, at a slight pressure drop from a smaller total core.", "price": "$450–1,100", "signal": "Front-mount", "links": []}, {"name": "Forge Twintercooler", "note": "Second core ahead of the crash bar in series with the factory one. Keeps the OEM core, so it's reversible; owners report it clearly beats stock on heat soak.", "price": "$800–1,000", "signal": "Hybrid", "links": []}, {"name": "Charge pipe sets (CTS, ECS, IE)", "note": "The FSI plastic turbo outlet pipe cracks with age and its DV port is a leak point; metal pipes are as much a repair as an upgrade at this age.", "price": "$250–450", "signal": "Do with the cooler", "links": []}], "tools": [{"name": "T25 and T30 Torx; 16 mm socket on a 3/8\" ratchet with a 6\" extension; long 5 mm hex; flat screwdriver for spring clamps"}, {"name": "Drain pan and funnel for coolant; a second pair of hands for the radiator", "only": ["stock"]}, {"name": "Hose-clamp pliers; T-bolt clamp driver (usually 8 mm or 10 mm)"}, {"name": "Step bit or hole saw only if your throttle body pipe needs the MAP sensor hole enlarged (kit sheet will say)", "only": ["pipes"]}], "before": ["Cold engine. The OE route drains the radiator; the front-mount route doesn't, but the couplers are stiff cold and easy hot, so warm the silicone in the sun.", {"only": ["stock"], "text": "Read the kit sheet for spacer and bolt lengths: IE ships different condenser and radiator bolts depending on whether your car has the ozone sensor on the radiator."}, {"only": ["fmic"], "text": "Check the kit's brackets against your crash beam before the bumper is off for the night; early and late Mk5 beams differ and ECS lists which."}, "Photograph the fog light and side marker plugs and the washer hose before the bumper comes off."], "steps": [{"n": 1, "chapter": "plan", "title": "Pick the style with your eyes open", "blocks": [{"t": "text", "b": "OE-location: cleaner, keeps radiator airflow, but the radiator comes out and coolant with it. Front-mount: cooler outlet, easier to service later, visible; some kits have less total core than stock and a touch more pressure drop, which ECS states plainly on its own page. Both beat the factory sandwich by a wide margin on heat soak."}, {"t": "ill", "id": "intercooler-temps", "cap": "The gap after run three is the whole argument."}]}, {"n": 2, "chapter": "plan", "title": "Decide on pipes now, not after", "blocks": [{"t": "text", "b": "The front is apart once. If the FSI's plastic turbo outlet pipe is original, it's fifteen years old and its DV port is a known leak; the throttle body pipe carries the MAP sensor and the noise pipe. Kits are sold with or without them; buy the version you'll actually fit."}, {"t": "note", "only": ["pipes"], "b": "Throttle body pipes drop the factory noise pipe. Order the firewall plug with the pipe or you'll drive around with a hole into the cabin."}]}, {"n": 3, "chapter": "access", "title": "Grille and bumper cover off", "blocks": [{"t": "text", "b": "T25s along the top of the grille, pull it from the bottom to free the lock tabs. Bumper cover: two T25 on top, five in each wheel well, ten along the bottom; undertray off (eight bolts). Pull the 'wings' at the fenders outward and lift the cover away, unplugging fog lights and side markers; headlight-washer cars unclip the hose at the pump and cap the tank. Slide the foam off the crash beam."}, {"t": "ill", "id": "bumper-fasteners", "cap": "Every T25 on the cover, front and underneath. Undertray bolts in grey."}]}, {"n": 4, "chapter": "access", "title": "Radiator support to service position", "only": ["stock"], "blocks": [{"t": "text", "b": "Factory airbox cars: two T25s on the air guide at the radiator support. Four 16 mm bolts each side hold the radiator support to the frame rails. Thread the two long M10 bolts into the outer lower holes first, then remove the rest and slide the support forward on the long bolts. It stays attached to the car; you get about four inches."}, {"t": "ill", "id": "ic-service-position", "cap": "Two long bolts in first, four 16 mm out each side, slide it forward. It stays on the car."}]}, {"n": 5, "chapter": "access", "title": "Hoses off and coolant out", "only": ["stock"], "blocks": [{"t": "text", "b": "Unclip both intercooler hoses at the core. Left hose off the throttle body pipe (screw clamp); right hose off the turbo outlet pipe (spring clip, flat screwdriver). Cap off, pan under, lower radiator hose unclipped to drain, upper hose unclipped. Fan shroud: four T30, unplug fans, out from below."}]}, {"n": 6, "chapter": "cooler", "title": "Radiator and old core out", "only": ["stock"], "caution": true, "blocks": [{"t": "text", "b": "Four T30 hold the radiator to the intercooler; radiator out from below and drained. Two T30 on top hold the intercooler to the support; remove them and tilt the intercooler and A/C condenser back a few inches together. Now the condenser-to-intercooler screws: four on the front face, one by the A/C lines on the right. Lift the old core off its locating pins and out the bottom; keep the plastic mount brackets."}, {"t": "warn", "b": "The condenser stays connected. Tilt it, never lever it; a kinked A/C line is a recharge and a new condenser."}, {"t": "ill", "id": "ic-sandwich", "cap": "The stack from the front: condenser, core, radiator, shroud, and how many bolts hold each to the next."}]}, {"n": 7, "chapter": "cooler", "title": "New core in", "only": ["stock"], "blocks": [{"t": "text", "b": "Plugs and cardboard off the new core; factory brackets slid on. In from the bottom, inlet and outlet facing rearward. Condenser bolted to it with the kit's M6×18 bolts, washers under the heads, the spacers between condenser and core. Locating pins into the support grommets, the two top bolts back in."}, {"t": "torque", "label": "Condenser-to-intercooler and radiator-to-intercooler bolts (M6)", "nm": 8, "c": {"level": "single", "n": 1, "note": "No figure in the kit sheet; M6 into cast aluminium tanks, snug. Over-tightening cracks a tank ear."}}]}, {"n": 8, "chapter": "cooler", "title": "Radiator back, fans, hoses", "only": ["stock"], "blocks": [{"t": "text", "b": "Radiator onto the new core with the kit's M6×14 bolts (M6×16 with the thin spacers on ozone-sensor cars). Fan shroud with the factory T30s. Fans plugged, coolant hoses clipped. If the radiator won't drop onto its lower mount, ease the A/C lines outward a little; they sit on it."}]}, {"n": 9, "chapter": "cooler", "title": "Couplers on", "only": ["stock"], "blocks": [{"t": "text", "b": "Take the o-ring off the factory right-hand hose and fit it to the kit's billet adapter; adapter into the turbo outlet pipe and clip it. Kit silicone: the L-shaped hose on the left to the throttle body pipe, the S-shaped on the right to the adapter. Clamps slid on first, then tightened."}, {"t": "note", "only": ["pipes"], "b": "Fitting new charge pipes too? Leave the couplers loose here and go to the pipes chapter before the final tighten."}, {"t": "ill", "id": "ic-oe-hoses", "cap": "L hose on the driver side to the throttle body pipe; S hose on the passenger side to the adapter."}]}, {"n": 6, "chapter": "cooler", "title": "Hang the core on the crash beam", "only": ["fmic"], "blocks": [{"t": "text", "b": "Brackets bolt to the existing crash-beam holes; ECS's need no drilling. Bolt the brackets to the core loosely, offer it up, and centre it in the bumper opening with the inlet on the passenger side (turbo side) and outlet on the driver's side. Tighten the beam bolts, then the bracket-to-core bolts."}, {"t": "warn", "b": "Check the core doesn't touch the beam or the bumper cover foam anywhere; a vibrating contact point wears through an end tank."}, {"t": "ill", "id": "ic-fmic-mount", "cap": "Brackets to the beam, core to the brackets, factory core left behind it."}]}, {"n": 7, "chapter": "cooler", "title": "Bypass the factory core", "only": ["fmic"], "blocks": [{"t": "text", "b": "Unclip the factory hose from the turbo outlet pipe (spring clip) and from the throttle body pipe (screw clamp). The factory sandwich core can stay where it is, sealed off, which is what the kits are designed around; removing it means the OE-location procedure's radiator-out work for no gain."}, {"t": "note", "b": "Some owners remove the stock core for airflow to the radiator. Fine, but it's the whole radiator-out job; do it only if the radiator is coming out anyway."}]}, {"n": 8, "chapter": "cooler", "title": "Route the new hoses", "only": ["fmic"], "blocks": [{"t": "text", "b": "Inlet run: turbo outlet pipe down and forward to the core's passenger-side tank. Outlet run: driver's tank up to the throttle body pipe. Couplers and clamps loose until every bend sits without twisting; then work along tightening. Nothing rubs the crash beam, the headlight or the bumper bracket."}, {"t": "note", "only": ["pipes"], "b": "Fitting charge pipes too? Leave the couplers loose and go to the pipes chapter first."}]}, {"n": 10, "chapter": "pipes", "title": "Turbo outlet pipe", "only": ["pipes"], "blocks": [{"t": "text", "b": "FSI: the plastic pancake pipe bolts to the turbo's compressor outlet with two T30 and carries the diverter valve on its port. Unbolt the DV (three T30) and move it to the new pipe with a new o-ring, fit the new pipe with its gasket or o-ring, and tighten the two T30. TSI: the kit pipe replaces the outlet elbow; same DV move."}, {"t": "torque", "label": "Turbo outlet pipe to compressor (2× T30)", "nm": 8, "c": {"level": "single", "n": 1, "note": "Small fasteners into the compressor cover; kit sheets say snug."}}, {"t": "ill", "id": "ic-charge-pipes", "cap": "The whole path, with the two pipes a kit replaces outlined in red."}]}, {"n": 11, "chapter": "pipes", "title": "Throttle body pipe and MAP sensor", "only": ["pipes"], "caution": true, "blocks": [{"t": "text", "b": "Unplug the MAP sensor and the noise pipe from the factory throttle body pipe, loosen the clamp at the throttle body and the hose clamp, and lift the pipe out. Move the MAP sensor to the new pipe's flange with its o-ring (two T25 or the kit's screws). Plug the noise-pipe hole in the firewall. New pipe onto the throttle body, clamp snug."}, {"t": "warn", "b": "The MAP sensor must seal or the car runs rich and throws codes. New o-ring, seated flat, screws snug. Cross-thread the aluminium flange and you're buying a pipe."}]}, {"n": 12, "chapter": "pipes", "title": "Couplers final", "only": ["pipes"], "blocks": [{"t": "text", "b": "Back to the couplers you left loose: every joint pushed fully home, clamps square on the hose, tightened firmly. T-bolt clamps want about 5 Nm; spring clips just seat. Wiggle every pipe; nothing should rotate."}]}, {"n": 13, "chapter": "finish", "title": "Support, bumper, grille", "blocks": [{"t": "text", "b": "OE route: radiator support bolts in (three in, then pull the long M10s, then the last two). Fog lights and side markers plugged, washer hose on, bumper cover on and its T25s, grille clicked in. Undertray: on the OE route one bolt fouls the new silicone; IE says pull that threaded insert and leave the bolt out."}]}, {"n": 14, "chapter": "finish", "title": "Coolant and first start", "only": ["stock"], "blocks": [{"t": "text", "b": "Fill with premixed G12++/G13, heater on hot, cap off, idle until the thermostat opens and the level settles, top up, cap on. Check both radiator hoses and the drain point for drips."}]}, {"n": 15, "chapter": "finish", "title": "Leak check and the heat-soak test", "blocks": [{"t": "text", "b": "Start, idle, listen at each coupler for a hiss under a light throttle blip. Then the test you did before you started: three back-to-back pulls in third with IAT logged. The number on pull three is the one that should have moved."}, {"t": "note", "b": "A slow boost leak shows in a week as an oily ring at a clamp and a soft top end. Recheck every clamp after the first drive and again after the first hot week."}]}], "alsoReplace": [{"name": "Diverter valve", "why": "It's in your hand when the turbo outlet pipe comes off. Piston valve or DV+; see that guide.", "only": ["pipes"]}, {"name": "Intercooler hoses (if the kit reuses them)", "why": "Factory hoses are the same age as the core and balloon under K04 boost. Silicone now while the front is open."}, {"name": "Thermostat and coolant temp sensor", "why": "Coolant is out on the OE route. Both are FSI weak spots.", "only": ["stock"]}, {"name": "Radiator and condenser fin comb", "why": "Fifteen years of stone damage; straighten the fins while both are on the bench.", "only": ["stock"]}, {"name": "Headlight-washer pump hose clip and fog light connectors", "why": "They break coming off; have them in the box."}], "check": {"tab": "Which style?", "title": "Which intercooler suits the car?", "illId": "intercooler-temps", "illCap": "Both upgraded curves beat stock; the choice is access vs airflow.", "rows": [{"see": "Stock or Stage 1, daily driver, wants factory look", "means": "OE-location core covers it with headroom.", "do": "APR, IE or CTS direct fit; no pipes needed yet."}, {"see": "Stage 2 or K04, hot climate, repeated pulls", "means": "Heat soak is your limit.", "do": "Either style; front-mount wins on outlet temp, OE-location on radiator airflow."}, {"see": "Original FSI pancake pipe, cracked or weeping at the DV", "means": "Pipe is a repair, not a mod.", "do": "Take the 'with charge pipes' kit."}, {"see": "Wants to keep the factory core and reversibility", "means": "Series second core.", "do": "Forge Twintercooler."}, {"see": "No lift, one afternoon, no coolant mess", "means": "Front-mount is the shorter job.", "do": "ECS or Eurojet kit, factory core left in place."}], "c": {"level": "community", "n": 4, "note": "Trade-offs from vendor documentation and owner reports; no independent bake-off between kits."}}, "aftercare": ["Recheck every clamp after the first drive and after the first hot week.", "Log IAT on three pulls a month into summer; if the third pull climbs again, look for a leak, not a bigger core.", "OE route: coolant level cold for a week."], "disagreements": [{"topic": "OE-location vs front-mount", "pos": "Front-mount vendors cite the coolest outlet temps and easy access; OE-location vendors cite radiator airflow and total core volume; one front-mount vendor admits a slight pressure drop and less core than stock.", "call": "Both are big improvements over the sandwich core. OE-location for a clean, radiator-friendly build; front-mount for hot climates and serviceability."}, {"topic": "Leave the factory core in on a front-mount", "pos": "Kits are designed around leaving it; some owners pull it for airflow.", "call": "Leave it unless the radiator is out anyway."}, {"topic": "Power claims", "pos": "Vendors quote 5–15 whp; the honest gain is the timing the tune stops pulling on hot pulls.", "call": "Buy it for repeatability, not the peak number."}], "sources": ["Integrated Engineering IETPCB1 Mk5/Mk6 FDS intercooler install guide (procedure, hardware)", "APR Intercooler System PQ35 page (core spec, five-pull heat-soak test)", "ECS Tuning Mk5 GTI/Jetta FMIC kit pages, with and without charge pipes (dimensions, dyno claims, noise-pipe note)", "IE FDS intercooler product listing (fitment, hose notes)", "golfmk6 owner thread on front-mount vs OE-location (Twintercooler experience)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();

-- 2. Diverter valve: second question (factory / drop-in electronic / Forge), aliases
insert into guides (id,content) values ('diverter-valve',$j${"id": "diverter-valve", "title": "Diverter valve replacement", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "dv-hero", "alsoFits": "Every 2.0T FSI/TSI with the K03 turbo (Mk5/Mk6 GTI, Jetta, A3, CC, Tiguan)", "category": "Engine", "kind": "repair", "variants": {"questions": [{"question": "Which engine?", "hint": "Same job, different part number.", "options": [{"id": "fsi", "label": "2.0T FSI (2006–2008.5)", "when": "Original diaphragm valve; replace with the piston-type revision"}, {"id": "tsi", "label": "2.0T TSI (2008.5–2009)", "when": "Early cars have the diaphragm valve; rev D is the fix"}]}, {"question": "Which valve?", "hint": "The factory piston valve is the right fix for a stock or Stage 1–2 car. Aftermarket valves split two ways: drop-in electronic units that keep the VW solenoid (GFB DV+, Turbosmart Kompact EM) and mechanical piston valves that need a vacuum line to the intake manifold (Forge).", "options": [{"id": "oe", "label": "Factory piston valve (VW)", "when": "Stock, Stage 1 or Stage 2. Cheapest, no fitting nuances."}, {"id": "dvplus", "label": "Drop-in electronic (GFB DV+, Turbosmart EM)", "when": "Tuned car, K04, or a factory piston valve that still leaks. Same three bolts; keeps the solenoid."}, {"id": "forge", "label": "Mechanical piston (Forge FMFSITVR)", "when": "Big-turbo or you want spring-adjustable behaviour. Adds a vacuum line and a solenoid bracket."}]}]}, "glance": {"timeFirst": "30 min", "timeRepeat": "15 min", "difficulty": 1.5, "cost": "$60–120", "risk": "Three bolts in an awkward spot; hot turbo", "why": "The diverter valve sits on the turbo and dumps boost back to the inlet when you lift off the throttle. The early one has a rubber diaphragm that tears, and then the turbo can't hold boost: soft power, a code, sometimes a flutter. VW's fix was a piston-type valve, and fitting it is three bolts.", "note": "Vendor sheets (Forge kit instructions, GFB and Turbosmart listings) and owner threads agree on parts; the only variable is reaching the bolts."}, "heroCap": "Three Torx bolts hold the valve to the turbo's compressor housing. Unplug, unbolt, swap, done.", "lifespan": {"title": "When to expect it", "headline": ["Original diaphragm valves commonly fail by 60,000–100,000 miles; sooner with a tune"], "earliest": "20k on tuned cars", "detail": "Symptoms: boost that builds then falls away, a code for underboost or a DV circuit fault, and sometimes a fluttering noise on lift-off. Tuned cars kill diaphragm valves fast because they run more pressure across them.", "factors": ["Tune", "Age of the rubber", "Heat"], "inspect": ["Any underboost code: pull the valve and look at the diaphragm"], "confidence": {"level": "community", "n": 4, "note": "Vendor articles and forum consensus."}}, "should": {"yesIf": ["Underboost codes (P0299) or DV codes (P0033, P0034)", "Boost builds then drops", "Fluttering on lift-off", "You've tuned it and still have the diaphragm valve"], "codes": ["P0299", "P0033", "P0034"], "notes": [{"text": "FSI part: the piston-type revision (06F 145 710 G) replaces the original diaphragm valves. Any 'D' rev TSI valve also physically fits and many owners use it.", "only": ["fsi"]}, {"text": "TSI part: 06H 145 710 D is the piston-type revision that replaces the earlier diaphragm valves (A, B, C). Buy D.", "only": ["tsi"]}, {"only": ["dvplus"], "text": "GFB DV+ (T9351) and Turbosmart Kompact EM keep the VW solenoid coil and replace only the valve mechanism with a billet body and sealed piston. Plug-and-play, no vacuum lines, no codes. The DV+ needs two minutes of assembly onto your solenoid; the Turbosmart is one piece."}, {"only": ["forge"], "text": "Forge FMFSITVR is a pressure/vacuum piston valve that mounts where the VW valve was and takes its vacuum reference from an intake-manifold tap included in the kit. The VW solenoid stays plugged in on a bracket so the ECU sees no fault. Longer install; the payoff is spring-adjustable behaviour at high boost."}], "confidence": {"level": "high", "n": 4, "note": "Part revisions and procedure consistent across DAP, ECS and forum threads."}}, "parts": [{"tier": "oe", "name": "Diverter valve, piston type", "pn": "06F 145 710 G", "note": "FSI", "price": "$60–90", "links": [], "only": ["fsi+oe"]}, {"tier": "oe", "name": "Diverter valve, revision D", "pn": "06H 145 710 D", "note": "TSI", "price": "$60–90", "links": [], "only": ["tsi+oe"]}, {"tier": "aftermarket", "name": "GFB DV+", "pn": "T9351", "note": "Billet body, brass piston; reuses your solenoid", "price": "$140–170", "links": [{"store": "UroTuning", "url": "https://www.urotuning.com/products/gfb-dv-diverter-valve-1-8t-2-0t-fsi-tsi-t9351"}], "only": ["dvplus"]}, {"tier": "aftermarket", "name": "Turbosmart Kompact EM plumb-back", "pn": "TS-0223-1263", "note": "One-piece electronic; direct swap", "price": "$200–250", "links": [], "only": ["dvplus"]}, {"tier": "aftermarket", "name": "Forge FMFSITVR replacement valve kit", "pn": "FMFSITVR", "note": "Valve, manifold tap, hose, solenoid bracket, springs", "price": "$200–260", "links": [{"store": "USP Motorsports", "url": "https://www.uspmotorsports.com/product/forge-diverter-valve-for-20t-black-75004707"}], "only": ["forge"]}, {"tier": "oe", "name": "O-ring for the valve flange", "pn": "in the box / N 906 254 01 style", "note": "Never reuse", "price": "$3", "links": []}], "aftermarket": [{"name": "GFB DV+ / Turbosmart Kompact EM", "note": "Fix the leak, keep the ECU's timing. The sensible upgrade for any tuned car; the factory piston valve leaks a little by design and can hang open after a hard shift.", "price": "$140–250", "signal": "Tuned cars", "links": []}, {"name": "Forge FMFSITVR", "note": "Mechanical piston with interchangeable springs. Slower to actuate than the ECU-driven valves, but adjustable and unbothered by 30 psi.", "price": "$200–260", "signal": "Big turbo", "links": []}, {"name": "Blow-off (vent-to-atmosphere) valves", "note": "Sound, at the cost of a rich stumble between shifts on a MAF car. Not recommended on the FSI.", "price": "$200–300", "signal": "Sound only", "links": []}], "tools": [{"name": "T30 Torx on a ¼\" ratchet with a wobble extension; a mirror"}, {"name": "Flat screwdriver for the connector lock"}, {"name": "5 mm hex for the Forge valve and bracket; hose cutter; a drill or step bit only if your manifold tap needs it (see the kit sheet)", "only": ["forge"]}], "before": ["Engine cold; the valve is on the turbo.", "Look at the new valve first so you know what you're feeling for: three bolt holes in a triangle and one connector."], "steps": [{"n": 1, "title": "Find it", "blocks": [{"t": "text", "b": "On the compressor (cold) side of the turbo, at the back of the engine on the driver's side: a round black valve with an electrical connector, held by three Torx bolts. Engine cover off; on some cars pulling the inlet pipe gives the room you need."}, {"t": "ill", "id": "dv-hero", "cap": "Three bolts in a triangle. The lower one is the awkward one."}]}, {"n": 2, "title": "Unplug and unbolt", "blocks": [{"t": "text", "b": "Slide the connector lock and unplug. Three T30 bolts; the bottom one usually needs the wobble extension and patience. Lift the valve out; note the o-ring."}]}, {"n": 3, "title": "Look at the old one", "blocks": [{"t": "text", "b": "A diaphragm valve shows a rubber disc; if it's torn or holed, that was your problem. A piston valve is the revision already; if it looks fine, your underboost is elsewhere (PCV, a split hose, the wastegate)."}]}, {"n": 4, "title": "Assemble the DV+ onto your solenoid", "only": ["dvplus"], "blocks": [{"t": "text", "b": "GFB's kit replaces the valve half. Pull the old plastic piston and spring off the solenoid body, fit the GFB body, brass piston and spring in the order the sheet shows, and seat the new o-ring. Turbosmart's Kompact EM skips this: it's a complete unit that plugs into your harness."}, {"t": "note", "b": "Keep the VW coil. It's the part that isn't broken and the ECU actuates it faster than any pneumatic valve could."}]}, {"n": 4, "title": "Fit the vacuum tap and bracket", "only": ["forge"], "blocks": [{"t": "text", "b": "The Forge valve needs a manifold reference. Fit the kit's tap to the intake manifold vacuum port it specifies (the tap has two spare ports for a boost gauge or meth trigger), run the hose to the valve's top port, and route it away from the passenger axle. Bolt the solenoid to the kit bracket on one of the valve's mounting holes and leave it plugged in; that's what keeps the fault codes away."}, {"t": "warn", "b": "Any hose near the axle or the turbo heat shield gets zip-tied clear. A chafed vacuum line is a valve that never opens."}]}, {"n": 5, "title": "New valve in", "blocks": [{"t": "text", "b": "New o-ring seated, valve in the same orientation, three bolts snug in turn (about 8 Nm; small bolts into aluminium). Connector on until it clicks. Forge: reuse the VW bolts with the bracket under one of them, then snug. Cover on."}, {"t": "torque", "label": "Diverter valve bolts (T30 ×3)", "nm": 8, "c": {"level": "single", "n": 1, "note": "Snug figure from kit sheets; no factory value confirmed this pass."}}]}, {"n": 6, "title": "Drive it", "blocks": [{"t": "text", "b": "Clear codes if you had them. Boost should hold to redline and the flutter should be gone."}]}], "alsoReplace": [{"name": "PCV valve", "why": "The other diaphragm on this engine, with overlapping symptoms. If one is original, the other is too."}, {"name": "Turbo inlet coupler and charge hoses", "why": "Split rubber is the other cause of underboost. Squeeze them while you're there."}], "check": {"tab": "Is it the DV?", "title": "Is the diverter valve the problem?", "illId": "dv-hero", "illCap": "Torn diaphragm settles it.", "rows": [{"see": "P0299 underboost, boost falls off", "means": "DV, PCV, or a leak.", "do": "DV first if it's the diaphragm type; it's cheap."}, {"see": "Flutter on lift-off", "means": "DV not sealing or opening late.", "do": "Replace."}, {"see": "Piston DV already fitted, still underboost", "means": "Not the DV.", "do": "PCV, charge hoses, wastegate actuator."}], "c": {"level": "community", "n": 3, "note": "Forum diagnosis and vendor articles."}}, "aftercare": ["None. If the code returns, move down the list above."], "disagreements": [{"topic": "Factory piston valve vs aftermarket", "pos": "Owners split: 'rev D and done' vs 'the piston valve leaks by design'. Vendors of both electronic drop-ins and mechanical valves claim sharper response.", "call": "Factory piston valve on stock and Stage 1–2. DV+ or Kompact on K04 and above, or when a piston valve car still shows soft boost after a shift. Forge mechanical only for big-turbo builds."}, {"topic": "Blow-off valves", "pos": "Sound good; MAF-metered engines run rich for a moment on each shift.", "call": "Not on the FSI."}], "sources": ["DAP 2.0T TSI common problems (DV section)", "ECS / vendor DV listings and revision notes", "Forum threads on DV symptoms and revisions", "Forge Motorsport 2.0T FSI replacement bypass valve kit instructions (ECS PDF)", "GFB DV+ T9351 and Turbosmart Kompact EM listings", "Audizine diverter valve information threads (piston valve leak-by-design, electronic vs pneumatic actuation)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('diverter-valve','bpy','diverter-valve','Diverter valve replacement','Engine',null,array['blow off valve','boost leak','bov','diverter valve','dv','dv+','forge dv','gfb','p0299','underboost']::text[],true,'30 min',1.5) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('diverter-valve-tsi','ccta','diverter-valve','Diverter valve replacement','Engine',null,array['blow off valve','boost leak','bov','diverter valve','dv','dv+','forge dv','gfb','p0299','underboost']::text[],true,'30 min',1.5) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;

